function chime(good=true){if(!progress.settings.sound)return;try{const a=new (window.AudioContext||window.webkitAudioContext)();[0,0.13,0.26].forEach((delay,i)=>{const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=(good?[523,659,784]:[330,294,262])[i];g.gain.setValueAtTime(0,a.currentTime+delay);g.gain.linearRampToValueAtTime(.07,a.currentTime+delay+.01);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+delay+.22);o.connect(g);g.connect(a.destination);o.start(a.currentTime+delay);o.stop(a.currentTime+delay+.23);});setTimeout(()=>a.close(),900);}catch{}}
