function renderMap(){const next=lessons.find(l=>l.id===progress.active?.lessonId)||lessons[Math.max(0,firstUnfinished())],complete=firstUnfinished()===-1,chapter=chapters[selectedChapter],group=lessons.filter(l=>l.chapter===selectedChapter),count=Object.keys(progress.completed).length,day=progress.days[dateKey()]||0;return `${heading('ИСКРА И ПОТЕРЯННЫЕ РУНЫ','Куда отправимся?','В каждой локации прячется новое заклинание.')}<div class="map-grid"><div class="map-main"><section class="next-lesson"><div class="hero-scene"></div><div class="hero-copy"><span class="tag">${icon('spark',14)} ${complete?'ВСЕ ЛОКАЦИИ ПРОЙДЕНЫ':'ТВОЙ СЛЕДУЮЩИЙ ШАГ'}</span><h2>${complete?'Теперь ты — хранитель логики':next.title}</h2><p>${complete?'Возвращайся к сложным местам и пробуй свои формулы.':'Искра ждёт тебя. '+next.subtitle+'.'}</p><div class="hero-meta"><span>${icon('clock',15)} 3–5 минут</span><span>+ до 45 XP</span></div><button class="primary" data-action="${progress.active?'resume':'start'}" data-id="${next.id}">${progress.active?'Продолжить урок':complete?'Снова в приключение':'В приключение'} ${icon('chevron',18)}</button></div><button class="hero-dragon" data-action="pet" aria-label="Погладить Искру"><img src="./assets/iskra.png" alt="Искра — мятный дракончик с золотым огоньком" fetchpriority="high" width="1254" height="1254"></button><span class="dragon-name">ИСКРА <span>твой спутник</span></span></section><section class="journey"><div class="section-title"><h2>Твой путь</h2><span>${count} / 24 урока</span></div><div class="chapter-tabs" role="group" aria-label="Локации">${chapters.map((c,i)=>`<button data-chapter="${i}" class="${i===selectedChapter?'selected':''}" aria-label="${c.name}" aria-pressed="${i===selectedChapter}"><span>${String(i+1).padStart(2,'0')}</span>${icon(lessons.filter(l=>l.chapter===i).every(l=>progress.completed[l.id])?'check':i===selectedChapter?'spark':'lock',15)}</button>`).join('')}</div><div class="world-panel ${chapter.color}"><div class="world-heading"><span class="world-number">${String(selectedChapter+1).padStart(2,'0')}</span><div><h3>${chapter.name}</h3><p>${chapter.topic}</p></div><span class="world-symbol" aria-hidden="true">${chapter.symbol}</span></div><div class="level-path">${[0,1,2].map(i=>`<button class="secret-spark secret-${i} ${secretSparks.has(String(i))?'caught':''}" data-secret="${i}" aria-label="Поймать тайный огонёк ${i+1}" ${secretSparks.has(String(i))?'disabled':''}>✦</button>`).join('')}${group.map((l,i)=>{const done=progress.completed[l.id],unlocked=lessonUnlocked(l);return `<div class="level-stop ${i%2?'lower':''}"><button class="level ${done?'done':unlocked?'current':'locked'}" data-action="${unlocked?'start':'locked'}" data-id="${l.id}" aria-label="${l.title}${done?', пройден':!unlocked?', закрыт':''}">${done?icon('check',29):unlocked?icon(i===3?'star':'practice',29):icon('lock',25)}</button><span class="level-stars" aria-label="${done?.stars||0} из 3 звёзд">${done?'★'.repeat(done.stars)+'☆'.repeat(3-done.stars):i===3?'ИСПЫТАНИЕ':String(lessons.indexOf(l)+1).padStart(2,'0')}</span><strong>${l.title}</strong></div>`;}).join('')}</div><div class="world-bottom">${icon('help',17)} ${selectedChapter===0?'Никакой подготовки. Начнём с самого простого.':'Каждый урок открывается после предыдущего.'}</div></div></section><button class="pet-adventure-cta pet-map-invite" data-nav="dragon"><span class="adventure-cta-icon">⌂</span><span><small>ТВОЙ ПИТОМЕЦ</small><strong>Дом, забота и маленькие истории</strong></span><b>→</b></button><button class="arena-map-link" data-nav="practice"><span>🏆</span><span><strong>Гонки драконов</strong><small>Собери искры, обгони соперников, выиграй кубок</small></span><b>→</b></button><button class="notebook-banner" data-action="notebook">${icon('book',26)}<span><strong>Из твоей тетради — в понятные шаги</strong><span>Джо, Джим, таблицы и законы де Моргана</span></span>${icon('chevron',20)}</button></div><aside class="right-rail"><section class="daily-card"><span class="mini-label">МАЛЕНЬКАЯ ЦЕЛЬ НА ДЕНЬ</span><div class="daily-ring" style="--p:${Math.min(100,day/2*100)}%"><div>${icon(day>=2?'check':'fire',32)}<strong>${Math.min(day,2)}<small> / 2</small></strong></div></div><h3>${day>=2?'На сегодня — получилось!':'Две искры в день'}</h3><p>${day>=2?'Можно отдохнуть. Или продолжить, если хочется.':'Два коротких занятия, чтобы новое стало понятным.'}</p><div class="week-dots">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return `<span class="${progress.days[dateKey(d)]?'filled':''} ${i===6?'today':''}" title="${dateKey(d)}">${progress.days[dateKey(d)]?icon('check',13):['вс','пн','вт','ср','чт','пт','сб'][d.getDay()]}</span>`;}).join('')}</div></section><button class="treasure-tease" data-nav="dragon"><img src="./assets/chest.png" width="1254" height="1254" alt="Сундук с находками"><span>Коллекция секретов</span><strong>${count} / 24</strong></button><div class="mini-progress"><div>${icon('dragon',20)}<strong>${dragonStage().name}</strong></div><p>${count<24?`До вершины: ${24-count} ${plural(24-count,'урок','урока','уроков')}`:'Все шесть локаций открыты'}</p><div class="progress-line"><i style="width:${count/24*100}%"></i></div></div></aside></div>`;}
function dragonStage(){const n=Object.keys(progress.completed).length;return n>=24?{name:'Хранитель логики',next:24}:n>=16?{name:'Искатель истин',next:24}:n>=8?{name:'Крылатый исследователь',next:16}:n>=4?{name:'Юный мыслитель',next:8}:{name:'Маленькая искра',next:4};}
function start(id,resume=false){const l=lessons.find(l=>l.id===id);if(!l||!lessonUnlocked(l)){toast('Сначала пройди предыдущий урок — он подготовит тебя к этому.');return;}if(!resume&&progress.active&&progress.active.lessonId!==id){showDialog('Сменить урок?',`<p>Текущий урок можно продолжить. Если начать другой, ответы внутри незавершённого урока сбросятся; пройденные уроки сохранятся.</p><button class="primary" data-action="switch-lesson" data-id="${id}">Начать выбранный урок</button><button class="secondary" data-action="close-dialog">Остаться</button>`);return;}advance.stop();view='lesson';session=(resume||progress.active?.lessonId===id)&&progress.active?{...progress.active,mode:'lesson'}:{lessonId:id,index:-1,errors:[],mode:'lesson'};feedback=null;result=null;combo=0;lootOpen=false;introState=session.intro||newIntro(l);resetAnswer();if(session.draft&&session.index>=0){({selection,tableValues,formulaValue,feedback}=restoreDraft(l.questions[session.index],session.draft));}persistSession();render();window.scrollTo(0,0);}
function persistSession(){if(session?.mode==='lesson'){progress.active={...session,intro:introState,draft:{selection,tableValues:{...tableValues},formulaValue}};save();}}
function resetAnswer(){advance.stop();rowMistake=null;selection=null;tableValues={};formulaValue='';hintOpen=false;theoryOpen=false;feedback=null;}
function currentQuestion(){if(session.mode==='arena'){const q=session.queue[session.index];return {q,lesson:lessons.find(l=>l.id===q.lessonId),key:'arena:'+session.index};}if(session.mode==='practice'){const key=session.queue[session.index];const [id,i]=key.split(':');return {q:lessons.find(l=>l.id===id).questions[Number(i)],lesson:lessons.find(l=>l.id===id),key};}const lesson=lessons.find(l=>l.id===session.lessonId);return {q:lesson.questions[session.index],lesson,key:`${lesson.id}:${session.index}`};}
function lessonHeader(title,total,index){return playHeader(title,total,index,icon);}
function renderLesson(){
  if(result)return renderResult();
  const lesson=lessons.find(l=>l.id===session.lessonId);
  const total=session.mode!=='lesson'?session.queue.length:lesson.questions.length;
  if(session.index===-1){introState??=newIntro(lesson);return renderIntro(lesson,introState,lessonHeader(lesson.title,total,0));}
  const {q,lesson:ql}=currentQuestion();
  return renderQuestion({q,lesson:ql,session,selection,tableValues,formulaValue,feedback,hintOpen,theoryOpen,rowMistake,combo,header:session.mode==='arena'?raceHeader(session,icon):lessonHeader(session.mode==='practice'?'Охота за искрами':lesson.title,total,session.index),icon});
}
function keyboard(target){return `<div class="symbol-keyboard" aria-label="Клавиатура логических символов">${['X','Y','Z','¬','∧','∨','→','↔','⊕','(',')'].map(s=>`<button type="button" data-insert="${s}" data-target="${target}" aria-label="Вставить ${OPS[s]?.name||s}">${s}</button>`).join('')}</div>`;}

function answerReady(q){return q.kind==='choice'?selection!==null:q.kind==='table'?Object.keys(tableValues).length===q.table.rows.length:formulaValue.trim().length>0;}
function rememberMistake(key){if(!session.errors.includes(key))session.errors.push(key);combo=0;if(session.mode==='arena')session.chain=0;else progress.reviews[key]={due:Date.now(),box:0};persistSession();save();}
function scheduleNext(){advance.stop();if(view==='expedition'){scheduleExpedition();return;}if(view!=='lesson'||result||!feedback?.good||document.hidden)return;const active=session,index=session.index;advance.start(()=>{if(view==='lesson'&&session===active&&session.index===index&&feedback?.good&&!result)next();});}
function check(){if(feedback||result||view!=='lesson')return;const {q,key}=currentQuestion();if(!answerReady(q))return;let good=false,text=q.why;
if(q.kind==='choice')good=selection===q.answer;else if(q.kind==='table'){const bad=q.table.rows.findIndex((r,i)=>r.result!==tableValues[i]);good=bad===-1;if(!good){const r=q.table.rows[bad];text=`Посмотри на строку ${bad+1}: ${Object.entries(r.env).map(([k,v])=>`${k} = ${v}`).join(', ')}. ${steps(parse(q.formula)).map(n=>`${format(n)} = ${evaluate(n,r.env)}`).join('; ')}. ${q.why}`;}}else{try{const a=parse(formulaValue);if(q.requireChange&&format(a)===format(parse(q.formula))){rememberMistake(key);feedback={good:false,text:'Ты переписал исходную формулу. Попробуй применить закон и записать её по-другому. '+q.hint};render();return;}const c=compare(formulaValue,q.expected);good=c.equivalent;if(!good)text=`Нашёлся контрпример: ${Object.entries(c.counterexample.env).map(([k,v])=>`${k} = ${v}`).join(', ')}. Твоя формула даёт ${c.counterexample.left}, а исходная — ${c.counterexample.right}. ${q.hint}`;}catch(e){rememberMistake(key);feedback={good:false,text:e.message};render();return;}}
feedback={good,text};combo=good?combo+1:0;if(!good){rememberMistake(key);}else if(session.mode==='arena'){session=awardAnswer(session,session.errors.includes(key));}else if(session.mode==='practice'){const previous=progress.reviews[key]||{box:0};const box=session.errors.includes(key)?0:Math.min(5,previous.box+1);progress.reviews[key]={box,due:Date.now()+[1,3,7,14,30,60][box]*86400000};}persistSession();save();chime(good);render();if(!good)$('#answer-feedback')?.scrollIntoView({behavior:progress.settings.motion?'smooth':'instant',block:'nearest'});}
function next(skipIntro=false){if(view!=='lesson'||!session||result)return;if(session.index===-1&&!skipIntro&&!introState?.solved)return;if(session.index>=0&&!feedback?.good)return;advance.stop();session.index++;const l=lessons.find(l=>l.id===session.lessonId),total=session.mode!=='lesson'?session.queue.length:l.questions.length;if(session.index>=total){lootOpen=false;if(session.mode==='arena'){const finished=recordRace(progress.arena,session.cupId,session.score);progress.arena=finished.arena;const xp=15+(session.score>=115?10:0);progress.xp+=xp;progress.days[dateKey()]=(progress.days[dateKey()]||0)+1;result={arena:true,xp,record:finished.record};}else if(session.mode==='practice'){const xp=15;progress.xp+=xp;progress.days[dateKey()]=(progress.days[dateKey()]||0)+1;result={xp,stars:session.errors.length?2:3,practice:true,total};}else result={...finishLesson(progress,l.id,session.errors.length,total),total};result.petReward=rewardPetLearning(progress.island);petPose='happy';petMessage='Мы принесли припасы! Теперь можно обустроить дом.';save();chime();}else{if(session.mode==='arena')session.gained=0;resetAnswer();delete session.draft;persistSession();save();}render();window.scrollTo({top:0,behavior:'instant'});}
function petRewardNote(){return '<button class="pet-earned" data-nav="dragon"><span>Для дома: +20 ракушек · +1 порция · +8 дружбы</span><strong>Порадовать питомца →</strong></button>';}
function renderResult(){if(result.arena)return raceResult(session,result)+petRewardNote();const lesson=lessons.find(l=>l.id===session.lessonId),nextLesson=lesson?lessons[lessons.indexOf(lesson)+1]:null;return renderLoot({result,lesson,nextLesson,opened:lootOpen,icon})+(lootOpen?petRewardNote():'');}
function renderPractice(){const due=dueReviews(progress),known=lessons.filter(l=>progress.completed[l.id]),all=Object.keys(progress.reviews).length;return `${arenaLobby(progress,challenge)}${heading('ТРЕНИРОВКА','Разомнём крылья')}<div class="practice-grid"><section class="feature-card review-feature"><span class="feature-symbol">${icon('practice',40)}</span><span class="tag">${due.length?`${due.length} ЗАДАНИЙ ЖДУТ ТЕБЯ`:'В ТВОЁМ ТЕМПЕ'}</span><h2>${due.length?'Преврати ошибки в опыт':'Пять маленьких открытий'}</h2><p>${due.length?'Вспомним то, что вызвало трудности. За одно занятие — до пяти задач с разбором.':known.length?'Короткая подборка из уже пройденных уроков. Никаких таймеров.':'Сначала пройди первый урок. Здесь появятся задания на повторение.'}</p><button class="primary" data-action="practice" ${!due.length&&!known.length?'disabled':''}>${due.length?'Разобрать сложное':'Начать практику'} ${icon('chevron',18)}</button><span class="field-hint">3–5 минут · +15 XP за занятие</span></section><section class="feature-card"><h3>Чтобы не забывалось</h3><p>Ошибки попадают сюда. После удачного повторения возвращаемся к задаче через 3, 7, 14, 30 и 60 дней. Если было трудно — уже завтра.</p><div class="big-number">${all}<small>заданий на повторении</small></div><p class="muted">${all&&!due.length?'Сейчас всё повторено. Можно тренироваться по желанию.':'Подсказки доступны в каждой задаче.'}</p></section></div><h2 class="section-heading">Повторить конкретную тему</h2><div class="lesson-list">${known.length?known.map(l=>`<button data-action="start" data-id="${l.id}"><span class="list-symbol">${chapters[l.chapter].symbol}</span><span><strong>${l.title}</strong><small>${l.subtitle}</small></span><span class="small-stars">${'★'.repeat(progress.completed[l.id].stars)}</span>${icon('chevron',18)}</button>`).join(''):'<div class="empty-state">Здесь будут твои пройденные уроки. Начни с «Правда или нет?» на карте.</div>'}</div>`;}
function startRace(id,invitation=null){const cup=CUPS.find(c=>c.id===id);if(!cup||!cupUnlocked(cup,progress.completed))return;advance.stop();const seed=invitation?.seed??crypto.getRandomValues(new Uint32Array(1))[0];session={...createRace(id,seededRandom(seed)),seed,challenge:invitation};combo=0;result=null;resetAnswer();view='lesson';render();window.scrollTo(0,0);}
let raceShare=null;
function shareRace(){if(!result?.arena)return;const url=new URL(location.href);url.hash=`challenge=${session.cupId}.${session.seed}.${session.score}`;url.search='';raceShare={title:'Вызов на гонку Искры',text:`Я набрал ${session.score} искр. Сможешь больше?`,url:url.href};showDialog('Брось вызов другу',`<p>Твой результат: <strong>${session.score} ✦</strong>. Друг получит те же 10 задач.</p><label class="field-label" for="race-link">Ссылка на трассу</label><input id="race-link" class="formula-input share-link" readonly value="${esc(url.href)}"><button class="primary wide" data-action="copy-race">Скопировать ссылку</button>${navigator.share?'<button class="secondary wide" data-action="native-share-race">Поделиться…</button>':''}<p class="field-hint" id="share-status" role="status">Отправь ссылку другу в любом мессенджере.</p>`);}
async function copyRace(){if(!raceShare)return;try{await navigator.clipboard.writeText(raceShare.text+' '+raceShare.url);$('#share-status').textContent='Скопировано! Можно отправлять другу.';}catch{$('#race-link').focus();$('#race-link').select();$('#share-status').textContent='Выделенная ссылка готова. Скопируй её через меню браузера.';}}
async function nativeShareRace(){if(!raceShare||!navigator.share)return;try{await navigator.share(raceShare);}catch(e){if(e.name!=='AbortError')$('#share-status').textContent='Используй кнопку «Скопировать ссылку».';}}

function startPractice(){advance.stop();combo=0;lootOpen=false;const due=dueReviews(progress).filter(key=>{const [id,i]=key.split(':');return lessons.find(l=>l.id===id)?.questions[i];});const pool=due.length?due:lessons.filter(l=>progress.completed[l.id]).flatMap(l=>l.questions.map((_,i)=>`${l.id}:${i}`));if(!pool.length)return;const queue=[...pool].sort(()=>Math.random()-.5).slice(0,5);session={mode:'practice',index:0,errors:[],queue};result=null;resetAnswer();view='lesson';render();window.scrollTo(0,0);}
function renderBook(){const op=OPS[selectedSymbol];return `${heading('ВСЕ ЗНАЧКИ ПОД РУКОЙ','Азбука логики','Сначала смысл. Сложное название запомнится потом.')}<div class="symbol-tabs" role="group" aria-label="Выбрать операцию">${Object.entries(OPS).map(([s,o])=>`<button data-symbol="${s}" class="${selectedSymbol===s?'active':''}" aria-label="${o.name}" aria-pressed="${selectedSymbol===s}">${s}</button>`).join('')}</div><section class="dictionary-card"><div class="dictionary-definition"><span class="giant-symbol">${selectedSymbol}</span><div><span class="eyebrow">ЧИТАЕТСЯ «${op.read.toUpperCase()}»</span><h2>${op.name}</h2><p>${op.rule}</p>${selectedSymbol==='¬'?'<p class="muted">Черта над буквой или выражением в тетради — тоже отрицание.</p>':''}</div></div>${staticTable(truthTable(selectedSymbol==='¬'?'¬X':`X ${selectedSymbol} Y`))}</section><div class="book-grid"><section class="feature-card"><h3>В каком порядке считать?</h3><ol class="thinking"><li>Сначала выражения в скобках.</li><li>Затем отрицание ¬.</li><li>Потом И ∧, затем ИЛИ ∨.</li><li>После — импликация → и эквиваленция ↔.</li></ol><p class="muted">Для ⊕, ↑, ↓ и повторяющихся стрелок ставь скобки: соглашения в учебниках могут отличаться.</p></section><section class="feature-card"><h3>Полезные равносильности</h3><div class="law-list"><p>¬¬X ≡ X</p><p>X → Y ≡ ¬X ∨ Y</p><p>¬(X ∧ Y) ≡ ¬X ∨ ¬Y</p><p>¬(X ∨ Y) ≡ ¬X ∧ ¬Y</p><p>X ∨ (X ∧ Y) ≡ X</p><p>X ∧ (Y ∨ Z) ≡ (X ∧ Y) ∨ (X ∧ Z)</p></div></section></div><section class="feature-card vocabulary"><h3>Ещё четыре полезных понятия</h3><dl><dt>Равносильность ≡</dt><dd>Формулы совпадают на всех наборах. А ↔ — операция внутри формулы, дающая 0 или 1.</dd><dt>Тавтология</dt><dd>Формула всегда истинна. Например, X ∨ ¬X.</dd><dt>Контрпример</dt><dd>Конкретный набор, на котором утверждение нарушается.</dd><dt>∀ и ∃</dt><dd>∀ читается «для всех», ∃ — «существует». В записи о равносильности ∀ означает проверку всех наборов, а для контрпримера достаточно существования одного набора. Логика предикатов — следующая отдельная тема.</dd></dl><p class="source-link">Справка: <a href="https://www.cs.cornell.edu/courses/cs2800/2016sp/handouts/pass_tseng_discmath.pdf" target="_blank" rel="noreferrer">курс дискретной математики Cornell</a>.</p></section>`;}
function staticTable(t){return `<div class="table-wrap"><table class="truth-table"><thead><tr>${[...t.vars,...(t.columns.length?t.columns:['Результат'])].map((c,i)=>`<th scope="col" class="${i>=t.vars.length?'computed':''}">${esc(c)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr>${t.vars.map(v=>`<td>${r.env[v]}</td>`).join('')}${(r.values.length?r.values:[r.result]).map((v,i,a)=>`<td class="${i===a.length-1?'result-col':''}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function renderLab(){return `${heading('ТВОИ ФОРМУЛЫ, ПОНЯТНЫЕ ШАГИ','Мастерская логики','Разбери свой пример или проверь, верно ли преобразование.')}<section class="lab-card"><div class="segmented"><button data-labtab="table" class="${labTab==='table'?'active':''}">Таблица истинности</button><button data-labtab="compare" class="${labTab==='compare'?'active':''}">Равносильность</button></div><form id="lab-form"><label class="field-label" for="lab-expression">${labTab==='compare'?'Первая формула':'Твоя формула'}</label><input id="lab-expression" class="formula-input" value="${esc(labExpr)}" spellcheck="false" autocomplete="off" maxlength="200" autocapitalize="characters">${labTab==='compare'?`<label class="field-label" for="lab-compare">Вторая формула</label><input id="lab-compare" class="formula-input" value="${esc(labCompare)}" spellcheck="false" autocomplete="off" maxlength="200" autocapitalize="characters">`:''}${keyboard('lab-expression')}<div class="lab-form-bottom"><p class="field-hint">До 3 переменных · ! = ¬ · &amp; = ∧ · | = ∨ · -&gt; = →<br>Ставь скобки, чтобы точно задать порядок.</p><button class="primary" type="submit">${labTab==='compare'?'Сравнить формулы':'Разобрать по шагам'} ${icon('chevron',18)}</button></div></form>${labError?`<div role="alert" class="notice">${esc(labError)}</div>`:''}</section>${labResult?renderLabResult():`<div class="lab-intro"><span>${icon('lab',29)}</span><div><strong>Таблица считает, а ты понимаешь</strong><p>Каждая маленькая операция получит свой столбец. Начни с примера выше.</p></div></div>`}<h2 class="section-heading">Примеры из твоей тетради</h2><div class="notebook-examples">${notebookExamples.map((e,i)=>`<button data-example="${i}"><span class="example-number">0${i+1}</span><span><strong>${e.title}</strong><span class="formula-small">${esc(e.formula)}</span></span>${icon('chevron',18)}</button>`).join('')}</div><p class="field-hint notebook-note">В примерах использованы читаемые фрагменты фотографий. Спорные записи проверяем математически; исходные фотографии остаются только в папке проекта.</p>`;}
function renderLabResult(){if(labResult.kind==='compare'){const c=labResult.data;return `<section class="lab-result"><div class="result-label ${c.equivalent?'yes':'no'}">${icon(c.equivalent?'check':'help',24)}<div><h2>${c.equivalent?'Формулы равносильны':'Формулы не равносильны'}</h2><p>${c.equivalent?'Результаты совпадают на всех '+c.rows.length+' наборах.':'Выделенные строки — контрпримеры: результаты различаются.'}</p></div></div><div class="table-wrap"><table class="truth-table"><thead><tr>${c.vars.map(v=>`<th>${v}</th>`).join('')}<th>${esc(labResult.a)}</th><th>${esc(labResult.b)}</th></tr></thead><tbody>${c.rows.map(r=>`<tr class="${r.left!==r.right?'counterexample':''}">${c.vars.map(v=>`<td>${r.env[v]}</td>`).join('')}<td>${r.left}</td><td>${r.right}</td></tr>`).join('')}</tbody></table></div></section>`;}const t=labResult.data,n=steps(parse(labResult.a)),ones=t.rows.filter(r=>r.result===1).length;return `<section class="lab-result"><h2>Вот как разобрать формулу</h2><ol class="calculation-steps">${n.length?n.map((node,i)=>`<li><span>${i+1}</span><div><strong>${esc(format(node))}</strong><p>${esc(OPS[node.op].rule)}</p></div></li>`).join(''):'<li>В формуле нет операций: значение равно указанной переменной или константе.</li>'}</ol>${staticTable(t)}<div class="table-conclusion">${icon('spark',20)}<p>${ones===t.rows.length?'Во всех строках 1 — это тавтология, тождественно истинная формула.':ones===0?'Во всех строках 0 — это противоречие, тождественно ложная формула.':`Результат зависит от набора: ${ones} строк с истиной, ${t.rows.length-ones} с ложью.`}</p></div></section>`;}
function solveLab(){labError='';try{labResult=labTab==='compare'?{kind:'compare',a:labExpr,b:labCompare,data:compare(labExpr,labCompare)}:{kind:'table',a:labExpr,data:truthTable(labExpr)};}catch(e){labResult=null;labError=e.message;}render();$('.lab-result, .notice')?.scrollIntoView({behavior:progress.settings.motion?'smooth':'instant',block:'nearest'});}
function renderDragonLegacy(){const count=Object.keys(progress.completed).length,stage=dragonStage(),stars=Object.values(progress.completed).reduce((a,v)=>a+v.stars,0);return `${heading('ТВОЙ ВЕРНЫЙ СПУТНИК','Знакомься, Искра','Каждое твоё открытие помогает ему расти.')}<div class="dragon-grid"><section class="dragon-room"><span class="tag">${stage.name.toUpperCase()}</span><button data-action="pet" class="pet-dragon" aria-label="Погладить Искру"><img src="./assets/iskra.png" alt="Дракончик Искра с огоньком в лапах" width="1254" height="1254"></button><h2>Искра</h2><p>«Я тоже не всё знаю. Давай разберёмся вместе?»</p><button class="secondary" data-action="pet">${icon('spark',18)} Дать пять</button><div class="dragon-stage-track">${['Первая искра','Мыслитель','Исследователь','Искатель','Хранитель'].map((s,i)=>`<span class="${count>=[0,4,8,16,24][i]?'reached':''}" title="${s}: ${[0,4,8,16,24][i]} уроков">${icon(i===4?'star':'spark',18)}</span>`).join('')}</div><p class="field-hint">${count<24?`До следующего звания: ${stage.next-count} ${plural(stage.next-count,'урок','урока','уроков')}`:'Вершина покорена. Приключение продолжается в мастерской!'}</p></section><div><section class="feature-card"><h3>Ваши открытия</h3><div class="achievement-stats"><div><strong>${count}</strong><span>${plural(count,'урок','урока','уроков')}</span></div><div><strong>${stars}</strong><span>${plural(stars,'звезда','звезды','звёзд')}</span></div><div><strong>${streak(progress.days)}</strong><span>${plural(streak(progress.days),'день','дня','дней')} подряд</span></div></div><div class="achievements">${[['Первая искра','Пройди первый урок',count>=1,'practice'],['Знаток символов','Пройди первые 8 уроков',lessons.slice(0,8).every(l=>progress.completed[l.id]),'book'],['Терпеливый исследователь','Занимайся 3 дня подряд',streak(progress.days)>=3,'fire'],['Хранитель логики','Пройди все 24 урока',count===24,'star']].map(([t,d,done,ic])=>`<div class="achievement ${done?'unlocked':''}"><span>${icon(ic,24)}</span><div><strong>${t}</strong><small>${d}</small></div>${done?icon('check',17):icon('lock',16)}</div>`).join('')}</div></section>${collection(lessons,progress)}<section class="feature-card settings-card"><h3>Твой комфорт</h3><label class="setting"><span>Звуки ответов</span><input type="checkbox" data-setting="sound" ${progress.settings.sound?'checked':''}><span class="switch"></span></label><label class="setting"><span>Анимация</span><input type="checkbox" data-setting="motion" ${progress.settings.motion?'checked':''}><span class="switch"></span></label><button class="settings-link" data-action="install">${icon('download',18)} Добавить на главный экран ${icon('chevron',16)}</button><p class="field-hint">Прогресс хранится в этом браузере. Для переноса на телефон сохрани файл и загрузи его там.</p><div class="backup-buttons"><button class="secondary" data-action="export">Сохранить прогресс</button><label class="secondary file-button">Загрузить<input type="file" id="import-progress" accept="application/json,.json"></label></div><button class="text-button danger" data-action="reset">Начать заново</button></section></div></div>`;}
function renderDragon(){return petHome(progress.island,{pose:petPose,message:petMessage,panel:petPanel,light:petLight,game:petGame})+'<details class="pet-legacy"><summary>Учёба, коллекция и настройки</summary>'+renderDragonLegacy()+'</details>';}
function render(){document.body.classList.toggle('playing',view==='lesson'||view==='expedition');document.body.classList.toggle('expedition-playing',view==='expedition');document.body.classList.toggle('pet-at-home',view==='dragon');document.body.classList.toggle('arena-playing',view==='lesson'&&session?.mode==='arena'&&!result);document.documentElement.classList.toggle('reduce-motion',!progress.settings.motion);$('#app').innerHTML=shell(view==='expedition'?expeditionView(progress.island,{hint:questHint}):view==='map'?renderMap():view==='lesson'?renderLesson():view==='practice'?renderPractice():view==='book'?renderBook():view==='lab'?renderLab():renderDragon());const field=$('#formula-answer');if(field&&!field.disabled)field.setSelectionRange(field.value.length,field.value.length);document.title=`${view==='expedition'?'Приключение':view==='lesson'?'Урок':nav.find(n=>n[0]===view)?.[1]||'Искра'} — Искра`;scheduleNext();}
function navigate(id){if(!nav.some(n=>n[0]===id))return;advance.stop();petGame=null;view=id;result=null;if(id==='map')selectedChapter=lessons[Math.max(0,firstUnfinished())]?.chapter||0;render();window.scrollTo(0,0);}
function showDialog(title,body){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>${body}`;$('#dialog').showModal();}
function showInstall(){if(installEvent){installEvent.prompt();installEvent=null;return;}showDialog('Искра на твоём телефоне',`<p>Открой ссылку игры в браузере телефона.</p><ol class="thinking"><li><strong>iPhone:</strong> в Safari нажми «Поделиться» → «На экран Домой».</li><li><strong>Android:</strong> в меню Chrome выбери «Установить приложение» или «Добавить на главный экран».</li></ol><p>После первого открытия игра сохраняет свои файлы и может работать без интернета. Прогресс остаётся на этом устройстве.</p><button class="primary wide" data-action="close-dialog">Понятно</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-nav]');if(!b||b.disabled)return;
if(handlePetAction(b,e))return;
if(b.dataset.race){startRace(b.dataset.race);return;}if(handlePlayAction(b,e))return;
if(b.dataset.nav){e.preventDefault();navigate(b.dataset.nav);return;}if(b.dataset.chapter!==undefined){selectedChapter=Number(b.dataset.chapter);render();return;}if(b.dataset.answer!==undefined){if(feedback||result)return;selection=Number(b.dataset.answer);persistSession();check();if(feedback?.good)burst();return;}if(b.dataset.cell!==undefined){const i=b.dataset.cell;tableValues[i]=tableValues[i]===undefined?0:1-tableValues[i];persistSession();render();return;}if(b.dataset.symbol){selectedSymbol=b.dataset.symbol;render();return;}if(b.dataset.labtab){labTab=b.dataset.labtab;labResult=null;labError='';render();return;}if(b.dataset.example!==undefined){const ex=notebookExamples[Number(b.dataset.example)];labExpr=ex.formula;labCompare=ex.compare||'';labTab=ex.compare?'compare':'table';solveLab();toast(ex.note);return;}
if(b.dataset.insert){const target=view==='lab'&&lastLabFocus==='lab-compare'?'lab-compare':b.dataset.target,el=document.getElementById(target);if(!el||el.disabled)return;const a=el.selectionStart??el.value.length,z=el.selectionEnd??a;el.setRangeText(b.dataset.insert,a,z,'end');el.dispatchEvent(new Event('input',{bubbles:true}));el.focus();return;}
const action=b.dataset.action;if(action==='start')start(b.dataset.id);if(action==='switch-lesson'){progress.active=null;start(b.dataset.id);}if(action==='resume')start(progress.active.lessonId,true);if(action==='next')next();if(action==='skip-intro')next(true);if(action==='check')check();if(action==='retry'){advance.stop();feedback=null;selection=null;persistSession();render();}if(action==='hint'){hintOpen=!hintOpen;render();}if(action==='theory'){theoryOpen=!theoryOpen;render();}if(action==='exit-lesson')navigate(session?.mode!=='lesson'?'practice':'map');if(action==='share-race')shareRace();if(action==='copy-race')copyRace();if(action==='native-share-race')nativeShareRace();if(action==='accept-challenge'&&challenge)startRace(challenge.cupId,challenge);if(action==='practice')startPractice();if(action==='locked')toast('Сначала пройди предыдущий урок — всё получится по шагам.');if(action==='notebook'){navigate('lab');$('.notebook-examples')?.scrollIntoView({behavior:progress.settings.motion?'smooth':'instant',block:'center'});}if(action==='pet'){burst(e.clientX,e.clientY);b.classList.remove('happy');void b.offsetWidth;b.classList.add('happy');chime();toast(['Искра: «Дай пять! Одно открытие за раз.»','Искра: «Ошибки не страшны. Я тоже учусь.»','Искра: «А ты уже знаешь, что 0 → 0 = 1?»'][Math.floor(Math.random()*3)]);}if(action==='close-dialog')$('#dialog').close();if(action==='install')showInstall();if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(progress,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`iskra-progress-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Файл прогресса сохранён.');}if(action==='reset')showDialog('Начать сначала?',`<p>Удалятся пройденные уроки, опыт, питомец, дом и очередь повторения в этом браузере. Можно сначала сохранить прогресс в файл.</p><button class="secondary" data-action="export">Сохранить файл</button><button class="danger-button" data-action="confirm-reset">Сбросить весь прогресс</button><button class="text-button" data-action="close-dialog">Отмена</button>`);if(action==='confirm-reset'){progress=fresh();save();session=null;navigate('map');toast('Новая экспедиция начинается.');}if(action==='confirm-import'&&pendingImport){progress=pendingImport;pendingImport=null;save();navigate('dragon');toast('Прогресс восстановлен.');}});
let lastLabFocus='lab-expression',pendingImport=null;
