function burst(x=innerWidth/2,y=Math.min(innerHeight*.45,380)){
  if(!progress.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const holder=document.createElement('div');holder.className='spark-burst';holder.style.left=x+'px';holder.style.top=y+'px';holder.setAttribute('aria-hidden','true');
  for(let i=0;i<14;i++){const bit=document.createElement('i');const a=i/14*Math.PI*2;bit.style.setProperty('--dx',Math.cos(a)*(60+i%4*20)+'px');bit.style.setProperty('--dy',Math.sin(a)*(65+i%3*27)+'px');bit.style.setProperty('--turn',i*61+'deg');bit.textContent=i%3?'✦':'·';holder.append(bit);}document.body.append(holder);setTimeout(()=>holder.remove(),1000);
}
function completePetJourney(){const reward=finishExpedition(progress.island);if(reward){progress.xp+=reward.xp;const day=dateKey();progress.days[day]=(progress.days[day]||0)+1;petPose='happy';petMessage='Мы вернулись! Посмотрим, что принесли?';save();chime();burst();}}
function scheduleExpedition(){
  const a=progress.island.active;if(document.hidden||!a?.passed)return;
  const id=a.id,step=a.step,delay=currentEncounter(progress.island)?.kind==='repair'?2400:1100;
  advance.start(()=>{if(view!=='expedition'||document.hidden||progress.island.active?.id!==id||progress.island.active?.step!==step)return;advanceEncounter(progress.island);if(progress.island.active?.step===5)completePetJourney();else save();questHint=false;render();window.scrollTo(0,0);},delay);
}
function handlePetAction(b,event){
  if(b.dataset.expedition){const active=beginExpedition(progress.island,b.dataset.expedition,Math.floor(Math.random()*4294967296));if(!active)return true;advance.stop();view='expedition';questHint=false;petPanel=null;petGame=null;if(active.step===5)completePetJourney();save();render();window.scrollTo(0,0);return true;}
  const qa=b.dataset.quest;
  if(qa||b.dataset.questToggle||b.dataset.questAnswer!==undefined){
    if(view!=='expedition')return true;
    if(qa==='exit'){navigate('dragon');return true;}
    if(b.dataset.questToggle)toggleExpeditionValue(progress.island,b.dataset.questToggle);
    if(qa==='retry')retryEncounter(progress.island);
    if(qa==='hint')questHint=!questHint;
    if(qa==='check'||b.dataset.questAnswer!==undefined){const good=answerEncounter(progress.island,b.dataset.questAnswer===undefined?null:Number(b.dataset.questAnswer));if(good!==null){chime(good);if(good)burst(event.clientX,event.clientY);}}
    save();render();if(progress.island.active?.feedback==='wrong')$('.quest-feedback')?.scrollIntoView({block:'nearest',behavior:'instant'});return true;
  }
  const action=b.dataset.pet;if(!action)return false;
  const s=progress.island;let outcome=null;if(['feed-panel','decor-panel','album-panel','stories'].includes(action))petGame=null;
  if(action==='rename'){showDialog('Как назовём друга?', '<form id="pet-name-form"><label class="field-label" for="pet-name">Имя питомца</label><input id="pet-name" class="formula-input" style="font:inherit;font-size:18px" maxlength="20" required value="'+esc(s.pet.name)+'"><button class="primary wide" type="submit">Сохранить имя</button></form>');return true;}
  if(action==='high-five'&&s.pet.bond>=12){petPose='happy';petMessage='Это наш секретный жест. Дай пять!';burst(event.clientX,event.clientY);chime();}
  if(action==='touch'){petPose=petPose==='curious'?'happy':'curious';petMessage=petPose==='happy'?'Щекотно! Дай лапу!':'Я тебя слушаю. Куда пойдём?';burst(event.clientX,event.clientY);}
  if(action==='play'){petGame={hits:0};petPanel=null;petPose='play';petMessage='Лови мяч! Нажми на него три раза.';}
  if(action==='catch-ball'&&petGame){petGame.hits++;chime();burst(event.clientX,event.clientY);if(petGame.hits===3){outcome=playPet(s);petGame=null;petPose='happy';outcome.message='Три из трёх! Вот это команда!';}}
  if(action==='stop-ball'){petGame=null;petPose='idle';petMessage='Поиграем ещё, когда захочешь.';}
  if(action==='feed'||action==='feed-favorite'){outcome=feedPet(s,action==='feed-favorite');if(outcome.ok){petPose='eat';chime();}}
  if(action==='cook')outcome=buyFavorite(s);
  if(action==='buy')outcome=buyDecoration(s,b.dataset.item);
  if(action==='equip'){toggleDecoration(s,b.dataset.item);petMessage='Можно переставлять, когда захочется.';}
  if(action==='upgrade'){outcome=upgradeHome(s);if(outcome.ok){petPose='happy';burst();}}
  if(action==='feed-panel')petPanel=petPanel==='food'?null:'food';
  if(action==='decor-panel')petPanel=petPanel==='decor'?null:'decor';
  if(action==='album-panel')petPanel=petPanel==='album'?null:'album';
  if(action==='stories')petPanel=petPanel==='stories'?null:'stories';
  if(action==='close-panel')petPanel=null;
  if(action==='lantern'){petLight=!petLight;petMessage=petLight?'Маленькие звёзды поселились дома.':'Тихий вечер. Светлячки отдыхают.';}
  if(action==='sleep'){petPose='sleep';petMessage='Пять минуточек… хр-р…';}
  if(action==='chimes'){petPose='happy';petMessage='Динь-динь! Музыка нашего дома.';chime();}
  const revealScene=outcome?.ok&&['feed','feed-favorite','buy','upgrade'].includes(action);if(revealScene)petPanel=null;
  if(outcome)petMessage=outcome.message+(outcome.gained?' +'+outcome.gained+' дружбы.':'');
  save();render();if(action==='chimes')$('.chimes')?.classList.add('swinging');if(revealScene||action==='play')window.scrollTo({top:0,behavior:'instant'});if(['feed-panel','decor-panel','album-panel','stories'].includes(action))$('#pet-panel')?.scrollIntoView({block:'nearest',behavior:'instant'});return true;
}
function handlePlayAction(b,event){
  const changeIntro=(key)=>{const lesson=lessons.find(l=>l.id===session.lessonId);if(!lesson||session.index!==-1)return;const wasSolved=introState.solved;introState=moveIntro(lesson,introState,key);session.intro=introState;persistSession();render();if(introState.solved&&!wasSolved){chime();burst();}};
  if(b.dataset.introToggle){changeIntro(b.dataset.introToggle);return true;}
  if(b.dataset.introPick!==undefined){changeIntro(Number(b.dataset.introPick));return true;}
  if(b.dataset.tableValue!==undefined){
    if(feedback||rowMistake)return true;const {q,key}=currentQuestion();const move=evaluateTableMove(q,tableValues,Number(b.dataset.tableValue));
    if(move.index===-1){check();return true;}if(!move.good){rememberMistake(key);rowMistake={text:briefFeedback({formula:q.formula,env:move.env},false,q.why)};persistSession();render();chime(false);return true;}
    tableValues[move.index]=move.expected;persistSession();if(move.done){check();}else{render();chime();}burst();return true;
  }
  if(b.dataset.collectible){const lesson=lessons.find(l=>l.id===b.dataset.collectible);if(!lesson)return true;const d=discoveryFor(lesson);showDialog(progress.completed[lesson.id]?d.name:'Пока это секрет',progress.completed[lesson.id]?'<div class="relic-detail">'+esc(d.symbol)+'</div><p>'+esc(d.rule)+'</p><button class="primary wide" data-action="start" data-id="'+lesson.id+'">Поиграть ещё раз</button>':'<p>Находка ждёт в приключении «'+esc(lesson.title)+'».</p><button class="primary wide" data-action="close-dialog">Буду искать!</button>');return true;}
  if(b.dataset.secret!==undefined){secretSparks.add(b.dataset.secret);burst(event.clientX,event.clientY);b.classList.add('caught');b.disabled=true;chime();if(secretSparks.size===3)toast('Секрет найден! Искра умеет чихать звёздами ✦');else toast('Огонёк пойман: '+secretSparks.size+' из 3');return true;}
  if(b.dataset.play==='wake'){changeIntro('X');return true;}
  if(b.dataset.play==='retry-row'){rowMistake=null;render();return true;}
  if(b.dataset.play==='keyboard'){const el=document.getElementById('formula-answer');if(el&&!el.disabled){el.inputMode='text';el.focus();}return true;}
  if(b.dataset.play==='erase'){const el=document.getElementById('formula-answer');if(el&&!el.disabled){const end=el.selectionEnd??el.value.length,start=el.selectionStart??end;el.setRangeText('',start===end?Math.max(0,start-1):start,end,'end');el.dispatchEvent(new Event('input',{bubbles:true}));el.focus();}return true;}
  if(b.dataset.play==='open-loot'){lootOpen=true;render();chime();burst();return true;}
  if(b.dataset.play==='pet'){b.classList.remove('happy');void b.offsetWidth;b.classList.add('happy');burst(event.clientX,event.clientY);chime();const bubble=document.querySelector('.dragon-bubble');if(bubble)bubble.textContent=['Апчхи… ✦','Щекотно!','Дай лапу!'][Math.floor(Math.random()*3)];return true;}
  return false;
}
